package com.speakertime;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.ZoneId;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.PluginPanel;

final class SpeakerTimePanel extends PluginPanel
{
    private final JTextField player = new JTextField();
    private final JTextField timeZone = new JTextField();
    private final JLabel status = new JLabel(" ");
    private final List<String> zoneChoices = SpeakerTimePlugin.timeZoneChoices();
    private final JList<String> zoneList = new JList<>();
    private boolean fillingZone;

    SpeakerTimePanel(SpeakerTimePlugin plugin)
    {
        setLayout(new BorderLayout(0, 8));
        add(new JLabel("Manual time zones"), BorderLayout.NORTH);

        JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
        JLabel playerLabel = new JLabel("RuneScape name");
        playerLabel.setLabelFor(player);
        form.add(playerLabel);
        form.add(player);

        JLabel zoneLabel = new JLabel("City or time zone");
        zoneLabel.setLabelFor(timeZone);
        form.add(zoneLabel);
        form.add(timeZone);
        form.add(new JLabel("Example: London or LA"));

        JButton save = new JButton("Save manual zone");
        JButton remove = new JButton("Remove manual zone");
        form.add(save);
        form.add(remove);
        form.add(status);
        add(form, BorderLayout.CENTER);
        add(createZoneBrowser(), BorderLayout.SOUTH);

        save.addActionListener(event ->
        {
            ZoneId zone = SpeakerTimePlugin.parseZone(timeZone.getText().strip());
            if (zone == null)
            {
                status.setText("Enter a recognized time zone.");
                return;
            }
            save(plugin, zone);
        });
        remove.addActionListener(event -> save(plugin, null));
    }

    private JPanel createZoneBrowser()
    {
        JPanel browser = new JPanel(new BorderLayout(0, 4));
        JLabel label = new JLabel("Choose a time zone");
        label.setLabelFor(zoneList);
        browser.add(label, BorderLayout.NORTH);

        zoneList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        JScrollPane scrollPane = new JScrollPane(zoneList);
        scrollPane.setPreferredSize(new Dimension(0, 330));
        browser.add(scrollPane, BorderLayout.CENTER);

        zoneList.addListSelectionListener(event ->
        {
            String selected = zoneList.getSelectedValue();
            if (!event.getValueIsAdjusting() && selected != null)
            {
                fillingZone = true;
                try
                {
                    timeZone.setText(selected);
                }
                finally
                {
                    fillingZone = false;
                }
            }
        });
        timeZone.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override
            public void insertUpdate(DocumentEvent event)
            {
                filterZones();
            }

            @Override
            public void removeUpdate(DocumentEvent event)
            {
                filterZones();
            }

            @Override
            public void changedUpdate(DocumentEvent event)
            {
                filterZones();
            }
        });
        filterZones();
        return browser;
    }

    private void filterZones()
    {
        if (fillingZone)
        {
            return;
        }

        String query = SpeakerTimePlugin.shortcutKey(timeZone.getText());
        zoneList.setListData(zoneChoices.stream()
            .filter(choice -> SpeakerTimePlugin.shortcutKey(choice).contains(query))
            .toArray(String[]::new));
    }

    private void save(SpeakerTimePlugin plugin, ZoneId zone)
    {
        String name = SpeakerTimePlugin.playerKey(player.getText());
        if (name.isEmpty() || name.chars().anyMatch(Character::isISOControl))
        {
            status.setText("Enter a RuneScape name.");
            return;
        }

        status.setText("Saving...");
        plugin.saveManualZone(name, zone, saved ->
            status.setText(!saved ? "Could not save the change."
                : zone == null ? "Manual zone removed." : "Manual zone saved."));
    }
}

package com.speakertime;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.channels.FileLock;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.text.Normalizer;
import java.time.DateTimeException;
import java.time.Instant;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "Speaker Time",
    internalName = "speaker-time",
    description = "Show chat timestamps in the speaker's shared time zone"
)
public class SpeakerTimePlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(SpeakerTimePlugin.class);
    private static final Pattern ANNOUNCEMENT = Pattern.compile("!tz(?::\\s*|\\s+)(.+)", Pattern.CASE_INSENSITIVE);
    private static final int MAX_SPEAKERS = 2048;
    private static final Set<ChatMessageType> PLAYER_CHAT = EnumSet.of(
        ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.PRIVATECHAT,
        ChatMessageType.MODPRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
        ChatMessageType.FRIENDSCHAT, ChatMessageType.CLAN_CHAT,
        ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT);
    private static final Map<String, ZoneId> ZONES = ZoneId.getAvailableZoneIds().stream()
        .collect(Collectors.toMap(id -> id.toLowerCase(Locale.ROOT), ZoneId::of, (first, second) -> first));
    private static final Pattern SHORTCUT_ACCENTS = Pattern.compile("\\p{M}+");
    private static final Pattern SHORTCUT_SEPARATORS = Pattern.compile("[\\s_-]+", Pattern.UNICODE_CHARACTER_CLASS);
    private static final Map<String, String> CITY_SHORTCUTS = cityShortcuts();
    private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("'['h:mm a']'", Locale.US);

    private static final DateTimeFormatter SHARED_CLOCK = new DateTimeFormatterBuilder()
        .parseCaseInsensitive()
        .appendPattern("h:mm a")
        .toFormatter(Locale.US)
        .withResolverStyle(ResolverStyle.STRICT);

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private ClientToolbar toolbar;

    private NavigationButton navigation;
    private volatile Map<String, ZoneId> savedZones = Map.of();

    @Override
    protected void startUp()
    {
        navigation = NavigationButton.builder()
            .tooltip("Speaker Time")
            .icon(ImageUtil.loadImageResource(SpeakerTimePlugin.class, "speaker-time.png"))
            .panel(new SpeakerTimePanel(this))
            .build();
        toolbar.addNavigation(navigation);

        executor.execute(() ->
        {
            try
            {
                savedZones = Map.copyOf(readZones(getPluginDirectory().join("shared-zones.tsv")));
            }
            catch (IOException e)
            {
                LOG.warn("Could not load Speaker Time's saved time zones", e);
            }
        });
    }

    @Override
    protected void shutDown()
    {
        toolbar.removeNavigation(navigation);
        clientThread.invoke(client::refreshChat);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!PLAYER_CHAT.contains(event.getType()) || event.getType() == ChatMessageType.PRIVATECHATOUT
            || event.getMessage() == null)
        {
            return;
        }

        String value = announcementValue(event.getMessage());
        if (value == null)
        {
            return;
        }

        String speaker = playerKey(event.getName());
        if (speaker.isEmpty() || speaker.chars().anyMatch(Character::isISOControl))
        {
            return;
        }

        if ("off".equalsIgnoreCase(value))
        {
            executor.execute(() -> updateSavedZone(speaker, null, false));
            return;
        }

        ZoneId zone = parseZone(value);
        if (zone == null && event.getTimestamp() > 0)
        {
            zone = parseClockOffset(value, event.getTimestamp());
        }
        if (zone != null)
        {
            ZoneId sharedZone = zone;
            executor.execute(() -> updateSavedZone(speaker, sharedZone, false));
        }
    }

    void saveManualZone(String speaker, ZoneId zone, Consumer<Boolean> onSaved)
    {
        executor.execute(() ->
        {
            boolean saved = updateSavedZone(speaker, zone, true);
            SwingUtilities.invokeLater(() -> onSaved.accept(saved));
        });
    }

    private boolean updateSavedZone(String speaker, ZoneId zone, boolean manual)
    {
        try
        {
            Filepath directory = getPluginDirectory();
            directory.createDirectories();
            Filepath saved = directory.join("shared-zones.tsv");
            // A second RuneLite window can write to the same plugin data directory.
            try (FileChannel channel = directory.join("shared-zones.lock")
                .openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE);
                FileLock lock = channel.lock())
            {
                Map<String, ZoneId> zones = readZones(saved);
                if (applyZone(zones, speaker, zone, manual))
                {
                    Filepath pending = directory.createTempFile("shared-zones-", ".tsv");
                    try
                    {
                        pending.write(encodeZones(zones));
                        pending.moveTo(saved, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
                    }
                    finally
                    {
                        pending.deleteIfExists();
                    }
                }
                savedZones = Map.copyOf(zones);
                clientThread.invokeLater(client::refreshChat);
                return true;
            }
        }
        catch (IOException e)
        {
            LOG.warn("Could not update Speaker Time's saved time zones", e);
            return false;
        }
    }

    static boolean applyZone(Map<String, ZoneId> zones, String speaker, ZoneId zone, boolean manual)
    {
        // A leading tab distinguishes a manual entry from older shared-only rows.
        String key = manual ? '\t' + speaker : speaker;
        if (zone == null)
        {
            boolean removed = zones.remove(key) != null;
            if (!manual)
            {
                removed |= zones.remove('\t' + speaker) != null;
            }
            return removed;
        }

        if (zone.equals(zones.get(key)))
        {
            return false;
        }

        zones.remove(key);
        zones.put(key, zone);
        if (zones.size() > MAX_SPEAKERS)
        {
            zones.remove(zones.keySet().iterator().next());
        }
        return true;
    }

    static ZoneId effectiveZone(Map<String, ZoneId> zones, String speaker)
    {
        ZoneId shared = zones.get(speaker);
        return shared != null ? shared : zones.get('\t' + speaker);
    }

    private static Map<String, ZoneId> readZones(Filepath saved) throws IOException
    {
        if (!saved.isFile())
        {
            return new LinkedHashMap<>();
        }

        try (var reader = saved.openBufferedReader())
        {
            return decodeZones(reader.lines().limit(MAX_SPEAKERS));
        }
        catch (UncheckedIOException e)
        {
            throw e.getCause();
        }
    }

    static Map<String, ZoneId> decodeZones(Stream<String> lines)
    {
        Map<String, ZoneId> zones = new LinkedHashMap<>();
        lines.forEach(line ->
        {
            int separator = line.indexOf('\t', 1);
            if (separator <= 0)
            {
                return;
            }

            try
            {
                zones.put(line.substring(0, separator), ZoneId.of(line.substring(separator + 1)));
            }
            catch (DateTimeException ignored)
            {
                // An invalid entry does not prevent loading the remaining players.
            }
        });
        return zones;
    }

    static String encodeZones(Map<String, ZoneId> zones)
    {
        StringBuilder data = new StringBuilder();
        zones.forEach((name, zone) -> data.append(name).append('\t').append(zone.getId()).append('\n'));
        return data.toString();
    }

    @Subscribe(priority = -1)
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!"chatMessageBuilding".equals(event.getEventName()))
        {
            return;
        }

        int uid = client.getIntStack()[client.getIntStackSize() - 1];
        MessageNode message = client.getMessages().get(uid);
        if (message == null || !PLAYER_CHAT.contains(message.getType()) || message.getTimestamp() <= 0)
        {
            return;
        }

        Player local = client.getLocalPlayer();
        String speaker = playerKey(message.getName());
        boolean ownMessage = message.getType() == ChatMessageType.PRIVATECHATOUT
            || (local != null && !speaker.isEmpty() && speaker.equals(playerKey(local.getName())));
        ZoneId zone = ownMessage ? ZoneId.systemDefault() : effectiveZone(savedZones, speaker);
        if (zone != null)
        {
            client.getObjectStack()[client.getObjectStackSize() - 1] = formatTime(message.getTimestamp(), zone);
        }
    }

    private static Map<String, String> cityShortcuts()
    {
        Map<String, String> cities = new HashMap<>();
        Set<String> ambiguous = new HashSet<>();
        for (String zone : new TreeSet<>(ZONES.keySet()))
        {
            int separator = zone.lastIndexOf('/');
            if (separator < 0 || zone.startsWith("etc/"))
            {
                continue;
            }

            String city = shortcutKey(zone.substring(separator + 1));
            String existing = cities.putIfAbsent(city, zone);
            if (existing != null && !ZONES.get(existing).getRules().equals(ZONES.get(zone).getRules()))
            {
                ambiguous.add(city);
            }
        }

        cities.keySet().removeAll(ambiguous);
        try (InputStream data = SpeakerTimePlugin.class.getResourceAsStream("time-zone-shortcuts.tsv"))
        {
            if (data != null)
            {
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(data, StandardCharsets.UTF_8)))
                {
                    reader.lines().forEach(line ->
                    {
                        String[] entry = line.split("\t", 2);
                        String zone = entry[0].toLowerCase(Locale.ROOT);
                        if (entry.length == 2 && ZONES.containsKey(zone))
                        {
                            for (String alias : entry[1].split("\\|"))
                            {
                                cities.put(shortcutKey(alias), zone);
                            }
                        }
                    });
                }
            }
        }
        catch (IOException | UncheckedIOException e)
        {
            LOG.warn("Could not load Speaker Time's extra time zone shortcuts", e);
        }
        return Map.copyOf(cities);
    }

    static String announcementValue(String message)
    {
        Matcher matcher = ANNOUNCEMENT.matcher(message.strip());
        return matcher.matches() ? matcher.group(1).strip() : null;
    }

    static ZoneId parseZone(String value)
    {
        String key = value.strip().replace(' ', '_').toLowerCase(Locale.ROOT);
        ZoneId zone = ZONES.get(key);
        return zone != null ? zone : ZONES.get(CITY_SHORTCUTS.getOrDefault(shortcutKey(value), key));
    }

    static List<String> timeZoneChoices()
    {
        Set<String> choices = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
        ZONES.values().forEach(zone -> choices.add(zone.getId()));
        CITY_SHORTCUTS.keySet().forEach(shortcut -> choices.add(shortcut.replace('_', ' ')));
        return List.copyOf(choices);
    }

    static String shortcutKey(String value)
    {
        String plain = SHORTCUT_ACCENTS.matcher(Normalizer.normalize(value.strip(), Normalizer.Form.NFD))
            .replaceAll("").toLowerCase(Locale.ROOT).replace(".", "").replace(",", "").replace("'", "").replace("’", "");
        return SHORTCUT_SEPARATORS.matcher(plain).replaceAll("_");
    }

    static ZoneOffset parseClockOffset(String value, long timestamp)
    {
        LocalTime reported;
        try
        {
            reported = LocalTime.parse(value, SHARED_CLOCK);
        }
        catch (DateTimeParseException ignored)
        {
            return null;
        }

        LocalTime utc = Instant.ofEpochSecond(timestamp).atOffset(ZoneOffset.UTC).toLocalTime();
        int difference = reported.toSecondOfDay() - utc.toSecondOfDay();
        // Current civil offsets are quarter-hour aligned. Snap to absorb typing and chat delays.
        int rounded = Math.floorDiv(difference + 450, 900) * 900;
        // Offsets one day apart display the same clock time.
        int wrapped = Math.floorMod(rounded + 43_200, 86_400) - 43_200;
        return ZoneOffset.ofTotalSeconds(wrapped);
    }

    static String formatTime(long timestamp, ZoneId zone)
    {
        return CLOCK.format(Instant.ofEpochSecond(timestamp).atZone(zone));
    }

    static String playerKey(String name)
    {
        return name == null ? "" : Text.removeTags(name).replace('\u00a0', ' ').strip().toLowerCase(Locale.ROOT);
    }
}

package com.speakertime;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SpeakerTimeLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SpeakerTimePlugin.class);
		RuneLite.main(args);
	}
}

package com.speakertime;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertNotNull;

public class SpeakerTimeTest
{
    @Test
    public void manualZoneChoicesIncludeShortcutsAndFullZoneIds()
    {
        List<String> choices = SpeakerTimePlugin.timeZoneChoices();
        assertTrue(choices.contains("pacific time"));
        assertTrue(choices.contains("America/Vancouver"));
        for (String choice : choices)
        {
            assertNotNull(choice, SpeakerTimePlugin.parseZone(choice));
        }
    }

    @Test
    public void curatedShortcutsResolveToTheirListedTimeZoneRules() throws IOException
    {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            SpeakerTimePlugin.class.getResourceAsStream("time-zone-shortcuts.tsv"), StandardCharsets.UTF_8)))
        {
            for (String line; (line = reader.readLine()) != null; )
            {
                String[] entry = line.split("\t", 2);
                ZoneId expected = ZoneId.of(entry[0]);
                for (String shortcut : entry[1].split("\\|"))
                {
                    ZoneId actual = SpeakerTimePlugin.parseZone(shortcut);
                    assertNotNull(shortcut, actual);
                    assertEquals(shortcut, expected.getRules(), actual.getRules());
                }
            }
        }
    }

    @Test
    public void acceptsAccentsAndPunctuationInShortcuts()
    {
        assertEquals(ZoneId.of("America/New_York"), SpeakerTimePlugin.parseZone("Washington, D.C."));
        assertEquals(ZoneId.of("America/Sao_Paulo"), SpeakerTimePlugin.parseZone("São Paulo"));
        assertEquals(ZoneId.of("America/Vancouver"), SpeakerTimePlugin.parseZone("Vancouver-BC"));
        assertEquals(ZoneId.of("Etc/GMT-7"), SpeakerTimePlugin.parseZone("Etc/GMT-7"));
    }

    @Test
    public void resolvesUsCoastsAndVancouverSeparately()
    {
        assertEquals(ZoneId.of("America/New_York"), SpeakerTimePlugin.parseZone("East Coast"));
        assertEquals(ZoneId.of("America/Los_Angeles"), SpeakerTimePlugin.parseZone(
            SpeakerTimePlugin.announcementValue("!tz WEST COAST")));
        assertEquals(ZoneId.of("America/Los_Angeles"), SpeakerTimePlugin.parseZone("Pacific Time"));
        assertEquals(ZoneId.of("America/Los_Angeles"), SpeakerTimePlugin.parseZone(
            SpeakerTimePlugin.announcementValue("!tz Pacific Time")));
        assertEquals(ZoneId.of("America/Vancouver"), SpeakerTimePlugin.parseZone("Vancouver"));
    }

    @Test
    public void sharedZoneOverridesSavedManualZoneAndOptOutClearsBoth()
    {
        String player = "goldzodia";
        ZoneId manual = ZoneId.of("Europe/London");
        ZoneId shared = ZoneId.of("America/Los_Angeles");
        Map<String, ZoneId> zones = new LinkedHashMap<>();

        SpeakerTimePlugin.applyZone(zones, player, manual, true);
        zones = SpeakerTimePlugin.decodeZones(SpeakerTimePlugin.encodeZones(zones).lines());
        assertEquals(manual, SpeakerTimePlugin.effectiveZone(zones, player));

        SpeakerTimePlugin.applyZone(zones, player, shared, false);
        zones = SpeakerTimePlugin.decodeZones(SpeakerTimePlugin.encodeZones(zones).lines());
        assertEquals(shared, SpeakerTimePlugin.effectiveZone(zones, player));

        SpeakerTimePlugin.applyZone(zones, player, null, false);
        assertEquals(Map.of(), SpeakerTimePlugin.decodeZones(SpeakerTimePlugin.encodeZones(zones).lines()));
    }

    @Test
    public void manualRemovalPreservesThePlayersShare()
    {
        Map<String, ZoneId> zones = SpeakerTimePlugin.decodeZones("goldzodia\tEurope/London".lines());
        SpeakerTimePlugin.applyZone(zones, "goldzodia", ZoneId.of("America/Los_Angeles"), true);
        SpeakerTimePlugin.applyZone(zones, "goldzodia", null, true);

        assertEquals(Map.of("goldzodia", ZoneId.of("Europe/London")), zones);
    }

    @Test
    public void savedZonesRoundTripAndRemovedEntriesStayCleared()
    {
        ZoneId london = ZoneId.of("Europe/London");
        ZoneOffset offset = ZoneOffset.ofHoursMinutes(5, 45);
        String saved = SpeakerTimePlugin.encodeZones(Map.of("gamer xy", london, "player b", offset));

        Map<String, ZoneId> restored = SpeakerTimePlugin.decodeZones(saved.lines());
        assertEquals(london, restored.get("gamer xy"));
        assertEquals(offset, restored.remove("player b"));

        saved = SpeakerTimePlugin.encodeZones(restored);
        assertEquals(Map.of("gamer xy", london),
            SpeakerTimePlugin.decodeZones((saved + "bad entry\tNot/AZone\n").lines()));
    }

    @Test
    public void acceptsClockAnnouncementsWithOrWithoutCommandColon()
    {
        assertEquals("1:40 pm", SpeakerTimePlugin.announcementValue("!Tz 1:40 pm"));
        assertEquals("1:40 pm", SpeakerTimePlugin.announcementValue("!tz: 1:40 pm"));
        assertEquals("LA", SpeakerTimePlugin.announcementValue("!tz:LA"));
        assertNull(SpeakerTimePlugin.announcementValue("!tzwhatever"));
    }

    @Test
    public void infersClockOffsetWithTypingDelay()
    {
        long timestamp = Instant.parse("2026-11-08T21:01:12Z").getEpochSecond();

        assertEquals("[1:05 PM]", SpeakerTimePlugin.formatTime(timestamp + 228,
            SpeakerTimePlugin.parseClockOffset("1:00 pm", timestamp)));
        assertNull(SpeakerTimePlugin.parseClockOffset("13:00 PM", timestamp));
        assertNull(SpeakerTimePlugin.parseClockOffset("1:00", timestamp));
    }

    @Test
    public void infersQuarterHourOffsetAcrossMidnight()
    {
        long timestamp = Instant.parse("2026-11-08T23:30:00Z").getEpochSecond();

        assertEquals("[5:15 AM]", SpeakerTimePlugin.formatTime(timestamp,
            SpeakerTimePlugin.parseClockOffset("5:15 AM", timestamp)));
    }

    @Test
    public void resolvesCityShortcuts()
    {
        assertEquals(SpeakerTimePlugin.parseZone("America/Los_Angeles"), SpeakerTimePlugin.parseZone("LA"));
        assertEquals(SpeakerTimePlugin.parseZone("America/Los_Angeles"), SpeakerTimePlugin.parseZone("Los Angeles"));
        assertEquals(SpeakerTimePlugin.parseZone("Europe/London"), SpeakerTimePlugin.parseZone("london"));
        assertEquals(SpeakerTimePlugin.parseZone("America/New_York"), SpeakerTimePlugin.parseZone("New York"));
        assertEquals(SpeakerTimePlugin.parseZone("Asia/Tokyo"), SpeakerTimePlugin.parseZone("Osaka"));
        assertEquals(SpeakerTimePlugin.parseZone("America/Argentina/Buenos_Aires"),
            SpeakerTimePlugin.parseZone("Buenos Aires"));
        assertNull(SpeakerTimePlugin.parseZone("CST"));
    }

    @Test
    public void formatsTheSameMessageInEachSpeakersZone()
    {
        long timestamp = Instant.parse("2026-11-08T21:00:00Z").getEpochSecond();

        assertEquals("[9:00 PM]", SpeakerTimePlugin.formatTime(timestamp,
            SpeakerTimePlugin.parseZone("Europe/London")));
        assertEquals("[1:00 PM]", SpeakerTimePlugin.formatTime(timestamp,
            SpeakerTimePlugin.parseZone("america/los angeles")));
    }

    @Test
    public void usesDaylightSavingRulesAtTheMessageTimestamp()
    {
        long timestamp = Instant.parse("2026-07-01T21:00:00Z").getEpochSecond();

        assertEquals("[2:00 PM]", SpeakerTimePlugin.formatTime(timestamp,
            SpeakerTimePlugin.parseZone("America/Los_Angeles")));
        assertNull(SpeakerTimePlugin.parseZone("not/a-zone"));
    }
}
